        logger.debug("Validation error at {} {}: {}", request.getMethod(), request.getRequestURI(), bindingResult.getFieldErrors());
        detail.setProperty("schemaValidationErrors", schemaValidationErrors);
        List<String> invalidFields = bindingResult.getFieldErrors().stream()
            .map(FieldError::getField).distinct().toList();
        detail.setProperty("errors", invalidFields);
        return ResponseEntity.status(status).body(detail);
